def test_defaults_and_toml():
    defaults = {"a": 1, "b": 2}
    toml = """[a]
    c = 3
"""
    with tempfile.NamedTemporaryFile(mode="w", suffix=".toml", delete=False) as f:
        f.write(toml)
        path = f.name
    try:
        cfg = load(defaults, toml_path=path)
        assert cfg == {"a": {"c": 3}, "b": 2}
    finally:
        os.unlink(path)


